package xi.arsenal;

import com.fs.starfarer.api.Global;
import com.fs.starfarer.api.combat.*;
import com.fs.starfarer.api.input.InputEventAPI;
import java.util.*;

/** Observes the real weapon/input entry independently of the optional upper-body Actor.
 * No trigger, callback replay, damage, controls or group state is manufactured here. */
public final class ZetaTetherEntryProbe {
    public static final String KEY="xi.arsenal.zeta.tether.entry";
    private static final int MAX_STATES=128,MAX_WEAPONS=256,MAX_GROUPS=64;
    private ZetaTetherEntryProbe(){}
    private static final class State {
        final CombatEngineAPI engine;final ShipAPI ship;long nativeFireEdges,nativeWeaponFiringEdges,onFireRequests,accepted,rejected,guardCalls;boolean firing;
        String lastGuard="Not observed",lastLauncherGuard="Not observed",rejectReason="",lastRequest="";final ArrayDeque<InputEventAPI> fireEvents=new ArrayDeque<>();
        State(CombatEngineAPI engine,ShipAPI ship){this.engine=engine;this.ship=ship;}
    }
    @SuppressWarnings("unchecked")private static Map<ShipAPI,State> registry(CombatEngineAPI engine){Object existing=engine.getCustomData().get(KEY+".registry");if(existing==null){Map<ShipAPI,State> created=new IdentityHashMap<>();engine.getCustomData().put(KEY+".registry",created);return created;}if(!(existing instanceof Map<?,?>))throw new IllegalStateException("Foreign tether entry registry");return (Map<ShipAPI,State>)existing;}
    private static State state(CombatEngineAPI engine,ShipAPI ship){if(engine==null||ship==null)return null;Map<ShipAPI,State> records=registry(engine);State found=records.get(ship);if(found!=null)return found;if(records.size()>=MAX_STATES)throw new IllegalStateException("Tether entry probe exceeds128 ships");State created=new State(engine,ship);records.put(ship,created);ship.setCustomData(KEY,created);return created;}
    public static void guard(CombatEngineAPI engine,WeaponAPI weapon,String reason){if(weapon==null||engine==null)return;State state=state(engine,weapon.getShip());state.guardCalls++;if(ZetaTetherCombo.COMMAND.equals(weapon.getId())){state.lastGuard=reason;boolean now=weapon.isFiring();if(now&&!state.firing)state.nativeWeaponFiringEdges++;state.firing=now;}else if(ZetaTetherCombo.LAUNCHER.equals(weapon.getId()))state.lastLauncherGuard=reason;}
    /** Call before ordinary native core controls. Merely records SHIP_FIRE; never consumes it. */
    public static void observeInput(CombatEngineAPI engine,List<InputEventAPI> events){if(engine==null||events==null)return;ShipAPI ship=engine.getPlayerShip();if(ship==null)return;WeaponGroupAPI selected=ship.getSelectedGroupAPI();if(selected==null||selected.getWeaponsCopy().stream().noneMatch(w->ZetaTetherCombo.COMMAND.equals(w.getId())||ZetaTetherCombo.LAUNCHER.equals(w.getId())))return;State state=state(engine,ship);for(InputEventAPI event:events)if(event!=null&&!event.isConsumed()&&!event.isRepeat()&&event.isControlDownEvent("SHIP_FIRE")){boolean seen=false;for(InputEventAPI prior:state.fireEvents)if(prior==event){seen=true;break;}if(!seen){state.nativeFireEdges++;state.fireEvents.addLast(event);if(state.fireEvents.size()>64)state.fireEvents.removeFirst();}}}
    public static void nativeRequest(CombatEngineAPI engine,WeaponAPI command,ZetaTetherCombo.Request result){State state=state(engine,command.getShip());state.onFireRequests++;state.lastRequest=result.reason();if(result.accepted()){state.accepted++;state.rejectReason="";}else{state.rejected++;state.rejectReason=result.reason();}}
    public static Map<String,Object> status(ShipAPI ship){Object value=ship==null?null:ship.getCustomData().get(KEY);if(!(value instanceof State state))return Map.of("observed",false,"reason","Native command/launcher callbacks have not been observed");return facts(state);}
    public static List<Map<String,Object>> snapshot(CombatEngineAPI engine){if(engine==null)return List.of();Object value=engine.getCustomData().get(KEY+".registry");if(!(value instanceof Map<?,?> records))return List.of();List<Map<String,Object>> result=new ArrayList<>();for(Object item:records.values())if(item instanceof State state)result.add(facts(state));return List.copyOf(result);}
    private static Map<String,Object> facts(State state){ShipAPI ship=state.ship;CombatEngineAPI engine=state.engine;Map<String,Object> row=new LinkedHashMap<>();row.put("observed",true);row.put("globalSame",Global.getCombatEngine()==engine);row.put("engineClass",engine.getClass().getName());row.put("contextClass",engine.getContext()==null?"":engine.getContext().getClass().getName());row.put("simulation",engine.isSimulation());row.put("campaignSimulation",engine.isInCampaignSim());row.put("missionSimulation",engine.isInMissionSim());row.put("pluginEnumeration","Public hasPluginOfClass only; engine exposes no public plugin enumeration");row.put("zetaPluginInstalled",engine.hasPluginOfClass(ZetaEnhancement.class));Object owner=engine.getCustomData().get(ZetaEnhancement.KEY+".owner");row.put("zetaOwnerKey",owner==null?"":owner.getClass().getName());row.put("zetaOwnerLive",ZetaEnhancement.instance(engine)!=null);row.put("tetherOwnerLive",ZetaTetherCombo.instance(ship)!=null);row.put("supportsLoadout",ZetaTetherCombo.supports(ship));row.put("hullId",ship.getHullSpec()==null?"":ship.getHullSpec().getHullId());row.put("variantId",ship.getVariant()==null?"":ship.getVariant().getHullVariantId());row.put("player",engine.getPlayerShip()==ship);row.put("alive",ship.isAlive());row.put("controlsLocked",ship.controlsLocked());row.put("paused",engine.isPaused());
        List<WeaponAPI> weapons=ship.getAllWeapons();if(weapons.size()>MAX_WEAPONS)throw new IllegalStateException("Tether entry weapon inventory exceeds budget");List<Map<String,Object>> inventory=new ArrayList<>();WeaponAPI command=null,launcher=null;for(WeaponAPI weapon:weapons){inventory.add(Map.of("id",Objects.toString(weapon.getId(),""),"slot",weapon.getSlot()==null?"":Objects.toString(weapon.getSlot().getId(),""),"type",String.valueOf(weapon.getType())));if(ZetaTetherCombo.COMMAND.equals(weapon.getId()))command=weapon;if(ZetaTetherCombo.LAUNCHER.equals(weapon.getId()))launcher=weapon;}row.put("allWeapons",List.copyOf(inventory));row.put("commandPresent",command!=null);row.put("launcherPresent",launcher!=null);row.put("command",weapon(command));row.put("launcher",weapon(launcher));
        List<WeaponGroupAPI> groups=ship.getWeaponGroupsCopy();if(groups.size()>MAX_GROUPS)throw new IllegalStateException("Tether entry groups exceed budget");List<Map<String,Object>> selectedGroups=new ArrayList<>();for(int i=0;i<groups.size();i++){WeaponGroupAPI group=groups.get(i);List<WeaponAPI> members=group.getWeaponsCopy();if(members.stream().noneMatch(w->ZetaTetherCombo.COMMAND.equals(w.getId())||ZetaTetherCombo.LAUNCHER.equals(w.getId())))continue;selectedGroups.add(Map.of("index",i,"number",i+1,"selected",ship.getSelectedGroupAPI()==group,"autofire",group.isAutofiring(),"members",members.stream().map(w->Objects.toString(w.getId(),"")).toList()));}row.put("nativeGroups",List.copyOf(selectedGroups));
        row.put("nativeFireEdges",state.nativeFireEdges);row.put("nativeWeaponFiringEdges",state.nativeWeaponFiringEdges);row.put("onFireRequests",state.onFireRequests);row.put("onFireAccepted",state.accepted);row.put("onFireRejected",state.rejected);row.put("onFireRejectReason",state.rejectReason);row.put("lastRequest",state.lastRequest);row.put("guardCalls",state.guardCalls);row.put("commandGuard",state.lastGuard);row.put("launcherGuard",state.lastLauncherGuard);return Collections.unmodifiableMap(row);}
    private static Map<String,Object> weapon(WeaponAPI weapon){if(weapon==null)return Map.of();Map<String,Object> row=new LinkedHashMap<>();row.put("type",String.valueOf(weapon.getType()));row.put("slotType",weapon.getSlot()==null?"":String.valueOf(weapon.getSlot().getWeaponType()));row.put("systemSlot",weapon.getSlot()!=null&&weapon.getSlot().isSystemSlot());row.put("decorative",weapon.isDecorative());row.put("disabled",weapon.isDisabled());row.put("forceDisabled",weapon.isForceDisabled());row.put("noFire",weapon.isForceNoFireOneFrame());row.put("firing",weapon.isFiring());row.put("charge",weapon.getChargeLevel());row.put("cooldown",weapon.getCooldownRemaining());row.put("ammo",weapon.getAmmo());row.put("callback",weapon.getEffectPlugin()==null?"":weapon.getEffectPlugin().getClass().getName());return Collections.unmodifiableMap(row);}
}
